import re
import time

def production_pipeline(config, input):
    start = time.time()
    tools = config.get("tools", {})
    guardrails = config.get("guardrails", {})
    memory = config.get("memory", None)
    for guard in guardrails.get("input_filter", []):
        if not guard(input):
            return {"status": "blocked", "reason": "Input blocked", "metadata": {"latency": time.time() - start, "safety": "failed"}}
    context = memory.get_context(input) if memory else input
    agent = config["agent"]
    result = agent(context, tools)
    output = result.get("answer", result.get("result", ""))
    for guard in guardrails.get("output_filter", []):
        if not guard(output):
            return {"status": "blocked", "reason": "Output blocked", "metadata": {"latency": time.time() - start, "safety": "failed"}}
    if memory:
        memory.add_message("user", input)
        memory.add_message("assistant", output)
    metadata = {"latency": time.time() - start, "tool_calls": result.get("tool_calls", 0), "safety": "passed", "tokens": len(output)}
    return {"status": "success", "output": output, "metadata": metadata}
